<?php require_once __DIR__.'/config/database.php';$pageTitle='নোটিশ বোর্ড';include __DIR__.'/includes/header.php';$rows=$pdo->query('SELECT * FROM notices WHERE status=1 ORDER BY id DESC')->fetchAll(PDO::FETCH_ASSOC);?><section class="section"><div class="container"><div class="section-heading center"><span>Notice Board</span><h2>নোটিশ বোর্ড</h2></div><?php foreach($rows as $r):?><article class="notice-card"><h3><?=htmlspecialchars($r['title'])?></h3><small><?=htmlspecialchars(date('d-m-Y',strtotime($r['published_at'])))?></small><p><?=nl2br(htmlspecialchars($r['body']))?></p></article><?php endforeach;?><?php if(!$rows):?><p class="empty">বর্তমানে কোনো নোটিশ নেই।</p><?php endif;?></div></section><?php include __DIR__.'/includes/footer.php';?>